SELECT callsign
FROM maritime.vessel_reference
WHERE name_cn LIKE '%海岳荷花%';

SELECT  operator_body_cn
FROM maritime.vessel_reference
WHERE name_cn LIKE '%海岳荷花%' ;

SELECT COUNT(*) 
FROM maritime.vessel_reference 
WHERE calibre = 1 LIMIT 50;

SELECT build_year_month
FROM maritime.vessel_reference
WHERE name_cn LIKE '%海岳荷花%';

SELECT AVG(dwt) AS average_dwt
FROM maritime.vessel_reference
WHERE calibre = 1;

SELECT AVG(teu) AS average_teu
FROM maritime.vessel_reference
WHERE calibre = 1;

SELECT AVG(speed) AS average_design_speed
FROM maritime.vessel_reference
WHERE calibre = 1;

SELECT build_year, class_society
FROM maritime.vessel_reference
WHERE name_cn LIKE '%海岳荷花%' LIMIT 50;

SELECT count(mmsi) FROM maritime.vessel_reference
WHERE grt > 50000
  AND EXTRACT(YEAR FROM AGE(CURRENT_DATE, TO_DATE(build_year, 'YYYY'))) < 10;

SELECT AVG(dwt) AS average_dwt
FROM maritime.vessel_reference
WHERE build_year_month >= TO_CHAR(NOW() - INTERVAL '1 year', 'YYYYMM');

SELECT COUNT(*) AS bad_weather_event_count FROM maritime.vessel_event_log ev JOIN maritime.vessel_reference fv ON ev.mmsi = fv.mmsi WHERE fv.name_cn LIKE '%海岳荷花%' 
AND ev.event_name_code = 'EVENT_RISK'  
AND ev.event_time >= NOW() - INTERVAL '3 months';

SELECT end_postime FROM maritime.vessel_state_history
WHERE mmsi IN (
    SELECT mmsi
    FROM maritime.vessel_reference
    WHERE name_cn LIKE '%海岳荷花%'
) AND is_new = 0 and dynamic_type = '5' AND leg_end_postime IS NOT NULL ORDER BY start_postime DESC LIMIT 1;

SELECT vessel_type, berth_num, moor_num
FROM maritime.port_efficiency_snapshot
WHERE port_code = 'CNSHA' AND year_month_day_hour = '2024-10-21-14';

SELECT COUNT(1)
FROM maritime.port_efficiency_snapshot
WHERE port_code = 'CNYTN' AND year_month = '2024-09' AND stay_dwt > 500000;

SELECT name_cn, lon, lat
FROM maritime.port_reference
WHERE unlocode LIKE 'CNSHA%';
